begin;
create table public.stadiums(id uuid primary key default gen_random_uuid(),slug text not null unique,name_he text not null,provider_name text unique,country text,city text,exterior_image_url text,image_credit text,image_license_url text,image_source_url text,official_url text,seating_map_url text,seating_map_image_url text,source_checked_at timestamptz,created_at timestamptz not null default now());
create table public.match_stadium_seating(match_id uuid primary key references public.matches,stadium_id uuid not null references public.stadiums,home_sectors text not null,away_sectors text not null,source_url text not null check(source_url ~ '^https://'),verified_at timestamptz not null default now(),updated_by uuid not null references public.profiles);
create table public.fan_public_photos(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles,album_photo_id uuid references public.fan_album_photos on delete set null,stadium_id uuid references public.stadiums,storage_path text not null unique,caption text not null default '' check(length(caption)<=300),status text not null default 'pending' check(status in('pending','approved','rejected','withdrawn')),approved_by uuid references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index fan_photo_one_active_album on public.fan_public_photos(album_photo_id) where album_photo_id is not null and status in('pending','approved');
alter table public.stadiums enable row level security;
alter table public.match_stadium_seating enable row level security;
alter table public.fan_public_photos enable row level security;
create function public.is_gallery_owner() returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from staff_memberships m join roles r on r.id=m.role_id where m.user_id=auth.uid() and m.suspended_at is null and r.key='owner')$$;
revoke all on function public.is_gallery_owner() from public;grant execute on function public.is_gallery_owner() to anon,authenticated,service_role;
create policy "stadiums public read" on public.stadiums for select using(true);
create policy "stadiums owner write" on public.stadiums for all to authenticated using(is_gallery_owner()) with check(is_gallery_owner());
create policy "seating public read" on public.match_stadium_seating for select using(true);
create policy "seating owner write" on public.match_stadium_seating for all to authenticated using(is_gallery_owner()) with check(is_gallery_owner() and updated_by=auth.uid());
create policy "public photos visible or own" on public.fan_public_photos for select using(status='approved' or user_id=auth.uid() or is_gallery_owner());
grant select on public.stadiums,public.match_stadium_seating,public.fan_public_photos to anon,authenticated;
grant insert,update on public.stadiums,public.match_stadium_seating to authenticated;
revoke insert,update,delete on public.fan_public_photos from anon,authenticated;
create function public.request_public_photo(p_album uuid default null,p_stadium uuid default null,p_caption text default '') returns public.fan_public_photos language plpgsql security definer set search_path=public,pg_temp as $$declare photo fan_public_photos;rid uuid:=gen_random_uuid();begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 if p_album is null and p_stadium is null then raise exception 'Photo context required';end if;
 if p_album is not null and not exists(select 1 from fan_album_photos where id=p_album and user_id=auth.uid()) then raise exception 'Private album unavailable';end if;
 if p_stadium is not null and not exists(select 1 from stadiums where id=p_stadium) then raise exception 'Stadium unavailable';end if;
 if length(coalesce(p_caption,''))>300 then raise exception 'Caption too long';end if;
 if (select count(*) from fan_public_photos where user_id=auth.uid() and created_at>now()-interval '1 day')>=30 then raise exception 'Daily upload limit';end if;
 insert into fan_public_photos(id,user_id,album_photo_id,stadium_id,storage_path,caption) values(rid,auth.uid(),p_album,p_stadium,auth.uid()||'/'||rid||'.jpg',coalesce(p_caption,'')) returning * into photo;return photo;
end$$;
create function public.withdraw_public_photo(p_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 update fan_public_photos set status='withdrawn',updated_at=now() where id=p_id and user_id=auth.uid();if not found then raise exception 'Photo unavailable';end if;
end$$;
create function public.review_public_photo(p_id uuid,p_status text) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin
 if not is_gallery_owner() then raise exception 'Forbidden';end if;
 if p_status not in('approved','rejected') then raise exception 'Invalid status';end if;
 update fan_public_photos set status=p_status,approved_by=auth.uid(),updated_at=now() where id=p_id and status='pending';if not found then raise exception 'Photo unavailable';end if;
 perform write_audit('photo.'||p_status,'fan_public_photos',p_id::text,null,null,jsonb_build_object('status',p_status));
end$$;
create function public.fan_public_profile(p_username text) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$select jsonb_build_object('user_id',p.id,'username',p.username,'display_name',p.display_name,'avatar_url',p.avatar_url,'club_name',c.name_he,'crest_url',c.crest_url) from profiles p left join clubs c on c.id=p.favorite_club_id where p.username=p_username limit 1$$;
revoke all on function public.request_public_photo(uuid,uuid,text),public.withdraw_public_photo(uuid),public.review_public_photo(uuid,text),public.fan_public_profile(text) from public,anon;
grant execute on function public.request_public_photo(uuid,uuid,text),public.withdraw_public_photo(uuid),public.review_public_photo(uuid,text) to authenticated;
grant execute on function public.fan_public_profile(text) to anon,authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('fan-public-albums','fan-public-albums',false,10485760,array['image/jpeg']);
create policy "public album upload allocated" on storage.objects for insert to authenticated with check(bucket_id='fan-public-albums' and exists(select 1 from fan_public_photos p where p.storage_path=name and p.user_id=auth.uid() and p.status='pending'));
create policy "public album approved or own read" on storage.objects for select to anon,authenticated using(bucket_id='fan-public-albums' and exists(select 1 from fan_public_photos p where p.storage_path=name and (p.status='approved' or p.user_id=auth.uid() or is_gallery_owner())));
create policy "public album storage boundary" on storage.objects as restrictive for select to anon,authenticated using(bucket_id<>'fan-public-albums' or exists(select 1 from fan_public_photos p where p.storage_path=name and (p.status='approved' or p.user_id=auth.uid() or is_gallery_owner())));
create policy "public album insert boundary" on storage.objects as restrictive for insert to authenticated with check(bucket_id<>'fan-public-albums' or exists(select 1 from fan_public_photos p where p.storage_path=name and p.user_id=auth.uid() and p.status='pending'));
create policy "public album anonymous insert boundary" on storage.objects as restrictive for insert to anon with check(bucket_id<>'fan-public-albums');
create policy "public album update boundary" on storage.objects as restrictive for update to anon,authenticated using(bucket_id<>'fan-public-albums') with check(bucket_id<>'fan-public-albums');
create policy "public album delete boundary" on storage.objects as restrictive for delete to anon,authenticated using(bucket_id<>'fan-public-albums');
commit;
